with l as (select id from vocab_theme_levels where theme_id = (select id from vocab_themes where slug = 'cuisine') and position = 2)
insert into vocab_theme_exercises (level_id, theme_id, position, type, content)
select l.id, (select id from vocab_themes where slug = 'cuisine'), v.position, v.type, v.content::jsonb from l, (values
(1, 'qcm', '{"question": "\"couper/hacher\" = ?", "options": ["preheat", "vegetarian", "allergy", "chop"], "correct_index": 3, "feedback_correct": "Correct !", "feedback_incorrect": "La bonne réponse est \"chop\"."}'),(2, 'qcm', '{"question": "\"fouetter\" = ?", "options": ["whisk", "stale", "undercooked", "drizzle"], "correct_index": 0, "feedback_correct": "Correct !", "feedback_incorrect": "La bonne réponse est \"whisk\"."}'),(3, 'matching', '{"instruction": "Relie le mot anglais à sa traduction.", "pairs": [{"left": "crispy", "right": "croustillant"}, {"left": "stale", "right": "rassis"}, {"left": "portion", "right": "portion"}, {"left": "leftover", "right": "reste (adj)"}], "feedback_correct": "Bravo !", "feedback_incorrect": "Regarde bien les mots."}'),(4, 'matching', '{"instruction": "Relie le mot anglais à sa traduction.", "pairs": [{"left": "garnish", "right": "garniture"}, {"left": "tender", "right": "tendre"}, {"left": "overcooked", "right": "trop cuit"}, {"left": "undercooked", "right": "pas assez cuit"}], "feedback_correct": "Bravo !", "feedback_incorrect": "Regarde bien les mots."}'),(5, 'fill_blank', '{"sentence_before": "\"réservation\" = ", "sentence_after": "", "correct_answers": ["reservation"], "feedback_correct": "Correct !", "feedback_incorrect": "\"réservation\" se dit \"reservation\" en anglais."}'),(6, 'true_false', '{"statement": "\"vegetarian\" veut dire \"végétarien\".", "correct_answer": true, "feedback_correct": "Correct !", "feedback_incorrect": "Regarde bien la traduction."}')
