(1, 'qcm', '{"question": "\"aux anges\" = ?", "options": ["self-conscious", "candid", "overjoyed", "tactful"], "correct_index": 2, "feedback_correct": "Correct !", "feedback_incorrect": "La bonne réponse est \"overjoyed\"."}'),(2, 'qcm', '{"question": "\"partagé/en conflit intérieur\" = ?", "options": ["disheartened", "level-headed", "hot-tempered", "conflicted"], "correct_index": 3, "feedback_correct": "Correct !", "feedback_incorrect": "La bonne réponse est \"conflicted\"."}'),(3, 'matching', '{"instruction": "Relie le mot anglais à sa traduction.", "pairs": [{"left": "melancholic", "right": "mélancolique"}, {"left": "euphoric", "right": "euphorique"}, {"left": "disheartened", "right": "découragé"}, {"left": "indignant", "right": "indigné"}], "feedback_correct": "Bravo !", "feedback_incorrect": "Regarde bien les mots."}'),(4, 'matching', '{"instruction": "Relie le mot anglais à sa traduction.", "pairs": [{"left": "level-headed", "right": "pondéré/calme"}, {"left": "hot-tempered", "right": "colérique"}, {"left": "tactful", "right": "diplomate/plein de tact"}, {"left": "blunt (personality)", "right": "direct/brusque"}], "feedback_correct": "Bravo !", "feedback_incorrect": "Regarde bien les mots."}'),(5, 'fill_blank', '{"sentence_before": "\"imperturbable\" = ", "sentence_after": "", "correct_answers": ["unfazed"], "feedback_correct": "Correct !", "feedback_incorrect": "\"imperturbable\" se dit \"unfazed\" en anglais."}'),(6, 'true_false', '{"statement": "\"candid\" veut dire \"franc/spontané\".", "correct_answer": true, "feedback_correct": "Correct !", "feedback_incorrect": "Regarde bien la traduction."}')
) as v(position, type, content);
